D['cycle']=r'''
.cycle[data-el="meridian-deck-cycle"]{display:block;isolation:isolate;--meridian-deck-nodecount:3}.cycle[data-el="meridian-deck-cycle"]:has(>.node:nth-child(4 of .node):last-child){--meridian-deck-nodecount:4}.cycle[data-el="meridian-deck-cycle"]:has(>.node:nth-child(5 of .node):last-child){--meridian-deck-nodecount:5}.cycle[data-el="meridian-deck-cycle"]:has(>.node:nth-child(6 of .node):last-child){--meridian-deck-nodecount:6}.cycle[data-el="meridian-deck-cycle"]::before{content:"";position:absolute;inset:20%;border:2px solid var(--a1-4-muted);border-radius:999px;z-index:-1}.cycle[data-el="meridian-deck-cycle"]>.core{position:absolute;left:37%;right:37%;top:40%;height:20%;display:flex;align-items:center;justify-content:center;padding:var(--gap-sm);border-radius:999px;background:var(--n-2);font-size:clamp(var(--type-14),2.8cqw,var(--type-30));font-weight:var(--name-weight);line-height:var(--name-line);text-align:center;color:var(--n-7)}.cycle[data-el="meridian-deck-cycle"]>.node{position:absolute;left:calc(50% + cos(-90deg + var(--meridian-deck-i)*360deg/var(--meridian-deck-nodecount))*33%);top:calc(50% + sin(-90deg + var(--meridian-deck-i)*360deg/var(--meridian-deck-nodecount))*33%);translate:-50% -50%;width:24%;height:26%;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:var(--gap-sm);gap:calc(var(--gap-sm)/2);border-radius:999px;background:var(--n-2);border:var(--stroke) solid var(--a1-4-muted);text-align:center;color:var(--n-7)}.cycle[data-el="meridian-deck-cycle"]>.node.on{background:var(--a1);color:var(--a1-on);border-color:var(--a1)}.cycle[data-el="meridian-deck-cycle"]>.node::after{content:"";position:absolute;left:calc(100% + var(--gap-sm));top:45%;width:8px;height:8px;border-top:2px solid var(--a1-4-muted);border-right:2px solid var(--a1-4-muted);rotate:calc(45deg + var(--meridian-deck-i)*360deg/var(--meridian-deck-nodecount));transform-origin:center}.cycle[data-el="meridian-deck-cycle"]>.node>.name{font-size:clamp(var(--type-12),2cqw,var(--type-24));font-weight:var(--name-weight);line-height:var(--name-line)}.cycle[data-el="meridian-deck-cycle"]>.node>.note{margin:0;font-size:clamp(var(--type-10),1.4cqw,var(--type-16));line-height:var(--body-line)}
'''
for i in range(1,7):D['cycle']+=f'.cycle[data-el="meridian-deck-cycle"]>.node:nth-child({i} of .node){{--meridian-deck-i:{i-1}}}\n'
common=lambda l:('[data-el="meridian-deck-'+l+'"]{box-sizing:border-box;position:relative;min-width:0;min-height:0;container-type:size;font-family:var(--font-body);font-size:var(--type-20);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);color:var(--ink)}\n[data-el="meridian-deck-'+l+'"] *{box-sizing:border-box}\n')
for leaf,s in D.items():(C/'elements'/leaf/'element.css').write_text(common(leaf)+s)
print('diagrams',','.join(D))
